// Native-only, offline large-fixture verification. Input files are generated by
// the companion streaming-writer probe and contain 2GiB +17 zero bytes.
// ignore_for_file: avoid_print
import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'package:koni_archive/io.dart' as koni;
import 'package:crisp_cloud/services/archive_streamed_reader.dart';
import 'package:crisp_cloud/services/archive_types.dart';

Future<void> main(List<String> args) async {
  if (args.length != 1) {
    throw ArgumentError('Pass one ZIP/7z/TGZ fixture path.');
  }
  final path = args.single;
  final name = path.split('/').last;
  final initial = ProcessInfo.currentRss;
  var peak = initial, ticks = 0;
  final timer = Timer.periodic(const Duration(milliseconds: 20), (_) {
    ticks++;
    final rss = ProcessInfo.currentRss;
    if (rss > peak) peak = rss;
  });
  final watch = Stopwatch()..start();
  final opened = await openStreamedArchiveSource(
    await koni.FileByteSource.open(path),
    name: name,
  );
  try {
    if (opened.policy.reason != null) throw StateError(opened.policy.reason!);
    final member = opened.archive.members.single;
    if (member.name != 'large.bin' ||
        member.size != 2 * 1024 * 1024 * 1024 + 17) {
      throw StateError('Unexpected fixture member.');
    }
    var count = 0, maxChunk = 0;
    await for (final chunk in opened.archive.openMember(
      member,
      maxBytes: kArchiveStreamingLimit,
    )) {
      if (chunk.any((byte) => byte != 0)) {
        throw StateError('A decoded fixture byte differs.');
      }
      count += chunk.length;
      if (chunk.length > maxChunk) maxChunk = chunk.length;
      final rss = ProcessInfo.currentRss;
      if (rss > peak) peak = rss;
    }
    if (count != member.size || maxChunk > 256 * 1024 || ticks == 0) {
      throw StateError('Streamed decode bounds or responsiveness failed.');
    }
    print(
      jsonEncode({
        'file': name,
        'decodedBytes': count,
        'maxChunk': maxChunk,
        'elapsedMs': watch.elapsedMilliseconds,
        'heartbeatTicks': ticks,
        'rssGrowthBytes': peak - initial,
        'peakRssBytes': peak,
      }),
    );
  } finally {
    await opened.archive.close();
    timer.cancel();
  }
}
